/* ════════════════════════════════════════════════════════════════════
   «Подземная лаборатория» — голос ОКО в блоках III–V: ещё реплики к
   событиям из oko.js и реакции на действия игрока.
   • b3 — «Отражение» (уровни 41–60): ОКО далеко, за стеклом, говорит
     «вы» и «носитель»; рядом, ближе и на полтона выше, его повторяет
     второй голос — Зрачок. Настоящее ОКО предупреждает: «Носитель, это
     ОКО…», «Слушайте меня, а не его», «не отвечайте второму голосу».
   • b4 — «Механизм» (61–80): ОКО почти союзник, говорит «ты» и
     «седьмой»; роботы слушаются Сторожа, а не ОКО; канцелярия, печати,
     накладные, конвейеры, Счетовод, Сказочник, Садовник, Судья.
   • b5 — «Исток» (81–100): ОКО слабое, шепчет «в паузах», его машины
     ему не подчиняются (сеть порога, протокол); корни, река, песня,
     игла «Заглушки»; нежно и устало, «вы».
   Реплики дописываются в LAB.OKO_LINES[блок][вид]; виды — те же, что в
   BASE (oko.js), и новые — отклики на действия игрока: kill_mech,
   kill_bio, kill_many, hurt, low_hp, heal, eat, drink, rest, capsule,
   bind, revive, note, mail, safe, pick, hack_ok, puzzle_ok, puzzle_fail,
   music, craft, buy, sell, trap_set, trap_kill, oko_trap, oko_trap_off,
   mines_order, grenade, quiet, idle, secret, zone, vault, floor, weapon,
   implant, survivor, turret_kill, patrol_slip.
   Подстановки: {L} — номер уровня, {F} — номер этажа (вид floor),
   {room} — название помещения (вид vault, всегда внутри «…»).
   Герой — без рода: ни прошедшего времени, ни прилагательных о нём в
   мужском или женском роде. Проверка — lab/tests/oko_lines_b.check.js.
   Синтаксис — не новее ES2018: файл читают и игра, и проверки в Node.
   ════════════════════════════════════════════════════════════════════ */
